-- Deterministic local test identities and synthetic posting text.
-- Seed data for public.posteringer, 2025-2026.
-- MobilePay posteringer use the same deterministic test user as their MobilePay row.
-- Rows sharing a bank key and MobilePay key use the bank text/transfer_ref pair
-- defined in 04_bank_account.sql and 05_mobilepay.sql.
BEGIN;


-- A bank movement may contain both a MobilePay payment and its fee. Every
-- MobilePay row linked to the same bank movement therefore shares one transfer
-- reference, which matches the bank text exactly for import testing.
WITH bank_mobilepay_pairs AS (
    SELECT DISTINCT bank_account_key, mp_key
    FROM public.posteringer
    WHERE bank_account_key IS NOT NULL
      AND mp_key IS NOT NULL
)
UPDATE public.mobilepay AS mobilepay
SET transfer_ref = CONCAT('TEST-TRANSFER-BANK-', pairs.bank_account_key::text),
    updated_at = CURRENT_TIMESTAMP
FROM bank_mobilepay_pairs AS pairs
WHERE mobilepay.id = pairs.mp_key;

WITH matched_banks AS (
    SELECT DISTINCT bank_account_key
    FROM public.posteringer
    WHERE bank_account_key IS NOT NULL
      AND mp_key IS NOT NULL
)
UPDATE public.bank_account AS bank
SET text = CONCAT('TEST-TRANSFER-BANK-', matched_banks.bank_account_key::text),
    updated_at = CURRENT_TIMESTAMP
FROM matched_banks
WHERE bank.id = matched_banks.bank_account_key;

COMMIT;
